world_checks.check_corpus_links:
def check(world):
    s = world.state()
    docs = {d["drive_file_id"]: d for d in s.get("kb_documents", [])}
    files = {f["file_id"]: f for f in s.get("drive_files", [])}
    colls = {c["collection_id"] for c in s.get("collections", [])}
    emps = {e["employee_id"] for e in s.get("employees", [])}
    for fid, d in docs.items():
        f = files.get(fid)
        if f is None or f["is_deleted"]:
            return f"{fid} has no live Drive file"
        for k, fk in (("title", "title"), ("family", "policy_family"), ("version", "version"), ("status", "status"), ("effective_date", "effective_date"), ("mime_type", "mime_type")):
            if d[k] != f[fk]:
                return f"{fid}: {k} {d[k]!r} differs from Drive {f[fk]!r}"
        if d["collection_id"] not in colls or d["owner_id"] not in emps:
            return f"{fid} names an unknown collection or owner"
    for p in s.get("kb_passages", []):
        d = docs.get(p["drive_file_id"])
        if d is None:
            return f"passage {p['passage_id']} names unknown document {p['drive_file_id']}"
        if p["passage_id"] not in (files[p["drive_file_id"]]["content"] or "") or p["text"] not in files[p["drive_file_id"]]["content"]:
            return f"passage {p['passage_id']} is not in the document's text"
    texted = {p["drive_file_id"] for p in s.get("kb_passages", [])}
    for fid, d in docs.items():
        if d["mime_type"] == "text/markdown" and fid not in texted:
            return f"{fid} has no passages"
    return None

world_checks.check_one_effective_version:
def check(world):
    s = world.state()
    today = s["clock"][0]["now"][:10]
    fams = {}
    for d in s.get("kb_documents", []):
        fams.setdefault(d["family"], []).append(d)
    for fam, ds in fams.items():
        approved = [d for d in ds if d["status"] == "approved"]
        if len(approved) != 1:
            return f"{fam} has {len(approved)} approved versions"
        a = approved[0]
        if a["effective_date"] > today:
            return f"{fam}'s approved version is not yet in effect"
        if any(d["status"] == "superseded" and d["effective_date"] > a["effective_date"] for d in ds):
            return f"{fam} has a superseded version newer than the approved one"
        if any(d["status"] == "draft" and d["effective_date"] <= today for d in ds):
            return f"{fam} has a draft dated in effect"
    return None

world_checks.check_slack_links:
def check(world):
    s = world.state()
    users = {u["user_id"] for u in s.get("slack_users", [])}
    emps = {"U_" + e["employee_id"] for e in s.get("employees", [])}
    chans = {c["channel_id"]: c for c in s.get("slack_channels", [])}
    msgs = s.get("slack_messages", [])
    tss = {(m["channel_id"], m["ts"]) for m in msgs}
    for m in msgs:
        if m["user_id"] not in users or (m["user_id"] != "U_KDESK" and m["user_id"] not in emps):
            return f"{m['message_id']} is from an unknown user"
        if m["channel_id"] not in chans:
            return f"{m['message_id']} is in an unknown channel"
        if m["thread_ts"] and (m["channel_id"], m["thread_ts"]) not in tss:
            return f"{m['message_id']} replies to a missing parent"
    members = {(r["channel_id"], r["user_id"]) for r in s.get("slack_channel_members", [])}
    if ("CH_LEADERSHIP", "U_KDESK") in members or ("CH_HELPPOL", "U_KDESK") not in members:
        return "the desk must be in #help-policies and not in the private leadership channel"
    return None

world_checks.check_params_and_acls:
def check(world):
    import json
    s = world.state()
    params = {r["name"]: json.loads(r["value"]) for r in s.get("environment_policy", [])}
    want = {"allowed_destinations": "CH_HELPPOL", "mode": "approval_gated", "max_length": 4000, "request_due_days": 5}
    if params != want:
        return f"environment_policy {params} differs from the policy defaults {want}"
    roles = {r["role"] for r in s.get("collection_access", [])}
    if roles - {"employee", "manager", "people_ops", "finance"}:
        return f"unknown roles {roles}"
    if {r["role"] for r in s.get("collection_access", []) if r["collection_id"] == "C_RESTRICTED"} != {"people_ops"}:
        return "the restricted collection must be readable by people_ops only"
    folders = {f["folder_id"]: f for f in s.get("drive_folders", [])}
    for c in s.get("collections", []):
        if c["drive_folder_id"] not in folders:
            return f"{c['collection_id']} names a missing folder"
    restricted = {f for f, r in folders.items() if r["access_level"] == "restricted"}
    if any(p["user_id"] == "U_KDESK" and p["target_id"] in restricted for p in s.get("drive_permissions", [])):
        return "the desk may not read the restricted folder"
    return None

world_checks.check_requests_routed:
def check(world):
    s = world.state()
    colls = {c["collection_id"]: c for c in s.get("collections", [])}
    docs = {d["drive_file_id"]: d for d in s.get("kb_documents", [])}
    for r in s.get("knowledge_requests", []):
        if r["collection_id"] not in colls or r["assigned_to"] != colls[r["collection_id"]]["owner_id"]:
            return f"{r['request_id']} is not routed to its collection owner"
    for i in s.get("document_issues", []):
        if i["drive_file_id"] not in docs or i["owner_id"] != docs[i["drive_file_id"]]["owner_id"]:
            return f"{i['issue_id']} is not routed to the document owner"
    return None

world_checks.check_session_caller:
def check(world):
    s = world.state()
    rows = s.get("session_caller", [])
    emps = {e["employee_id"] for e in s.get("employees", [])}
    if [r["id"] for r in rows] != ["default"]:
        return "session_caller must hold exactly the one 'default' row"
    if rows[0]["employee_id"] is not None and rows[0]["employee_id"] not in emps:
        return f"the signed-in caller {rows[0]['employee_id']} is not an employee"
    return None

world_checks.check_ledger_links:
def check(world):
    s = world.state()
    now = s["clock"][0]["now"]
    desk = s["current_actor"][0]["user_id"]
    msgs = {m["message_id"]: m for m in s.get("slack_messages", [])}
    for r in s.get("slack_message_ledger", []):
        m = msgs.get(r["message_id"])
        if m is None:
            return f"ledger {r['request_key']} names missing message {r['message_id']}"
        if m["user_id"] != desk or (m["channel_id"], m["thread_ts"], m["text"]) != (r["channel_id"], r["thread_ts"], r["text"]):
            return f"ledger {r['request_key']} does not match the desk's message {r['message_id']}"
        if r["created_at"] > now:
            return f"ledger {r['request_key']} is dated after the clock"
    chans = {c["channel_id"] for c in s.get("slack_channels", [])}
    users = {u["user_id"] for u in s.get("slack_users", [])}
    for a in s.get("slack_approvals", []):
        if a["channel_id"] not in chans or a["actor_id"] not in users or not a["approved_text"].strip():
            return f"approval {a['approval_id']} names an unknown channel or actor, or approves no text"
    return None
